import{_ as o,C as l,o as s,c as h,j as e,a as t,E as n,w as i,am as p}from"./chunks/framework._FJXuPhs.js";const b=JSON.parse('{"title":"人工智能概念","description":"","frontmatter":{},"headers":[],"relativePath":"框架/AI 框架/Spring AI/MCP Java SDK：标准与架构全面分析/Spring AI 官方博客内容 概述.md","filePath":"框架/AI 框架/Spring AI/MCP Java SDK：标准与架构全面分析/Spring AI 官方博客内容 概述.md","lastUpdated":null}'),g={name:"框架/AI 框架/Spring AI/MCP Java SDK：标准与架构全面分析/Spring AI 官方博客内容 概述.md"};function d(c,r,u,A,m,I){const a=l("font");return s(),h("div",null,[r[12]||(r[12]=e("h2",{id:"简介",tabindex:"-1"},[t("简介 "),e("a",{class:"header-anchor",href:"#简介","aria-label":'Permalink to "简介"'},"​")],-1)),r[13]||(r[13]=e("p",null,[e("img",{src:"https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/spring_ai_logo_with_text.svg",alt:"Integration Problem"})],-1)),r[14]||(r[14]=e("p",null,[t("项目 "),e("code",null,"Spring AI"),t(" 旨在简化集成人工智能功能的应用程序开发，避免不必要的复杂性。")],-1)),r[15]||(r[15]=e("p",null,"该项目汲取了诸如LangChain和LlamaIndex等著名Python项目的灵感，但Spring AI并非这些项目的直接移植。",-1)),e("p",null,[r[1]||(r[1]=t("创立此项目基于一个信念：下一波",-1)),n(a,{color:"#ff0000"},{default:i(()=>[...r[0]||(r[0]=[t("生成式AI应用不仅限于Python开发者，而是将跨越多种编程语言",-1)])]),_:1}),r[2]||(r[2]=t("，无处不在。",-1))]),r[16]||(r[16]=p('<table tabindex="0"><thead><tr><th></th><th>Spring AI 解决了AI集成的基本挑战： <code>将您的企业数据和 API 与 AI 模型相连接</code>.</th></tr></thead></table><p>Spring AI 为开发人工智能应用提供了基础抽象。 这些抽象具有多种实现，使得在最少代码改动的情况下轻松实现组件替换。</p><p>Spring AI 提供以下功能：</p><ul><li>跨AI提供商的便携式API支持，涵盖聊天、文本转图像和嵌入模型。同时支持同步和流式API选项。还可访问特定于模型的功能。</li><li>支持所有主流的AI模型提供商，如Anthropic、OpenAI、Microsoft、Amazon、Google和Ollama。支持的模型类型包括：</li><li><a href="https://www.spring-doc.cn/spring-ai/1.1.3/api_structured-output-converter.html" target="_blank" rel="noreferrer">结构化输出</a> - AI模型输出到POJOs的映射。</li><li>支持所有主要的 <a href="https://www.spring-doc.cn/spring-ai/1.1.3/api_vectordbs.html" target="_blank" rel="noreferrer">向量数据库提供商</a> ，如Apache Cassandra、Azure Cosmos DB、Azure Vector Search、Chroma、Elasticsearch、GemFire、MariaDB、Milvus、MongoDB Atlas、Neo4j、OpenSearch、Oracle、PostgreSQL/PGVector、Pinecone、Qdrant、Redis、SAP Hana、Typesense和Weaviate。</li><li>跨向量存储提供者的便携式API，包括一个新颖的类SQL元数据过滤API。</li><li><a href="https://www.spring-doc.cn/spring-ai/1.1.3/api_tools.html" target="_blank" rel="noreferrer">工具/函数调用</a> - 允许模型请求执行客户端工具和函数，从而根据需要访问实时信息并采取行动。</li><li><a href="https://www.spring-doc.cn/spring-ai/1.1.3/observability_index.html" target="_blank" rel="noreferrer">可观察性</a> - 提供对AI相关操作的洞察。</li><li>数据工程的文档摄入 <a href="https://www.spring-doc.cn/spring-ai/1.1.3/api_etl-pipeline.html" target="_blank" rel="noreferrer">ETL框架</a> 。</li><li><a href="https://www.spring-doc.cn/spring-ai/1.1.3/api_testing.html" target="_blank" rel="noreferrer">AI模型评估</a> - 用于帮助评估生成内容并防止出现虚幻响应的实用工具。</li><li>Spring Boot 对 AI 模型和向量存储的自动配置与Starters。</li><li><a href="https://www.spring-doc.cn/spring-ai/1.1.3/api_chatclient.html" target="_blank" rel="noreferrer">ChatClient API</a> - 与AI聊天模型通信的流畅API，语法上类似于WebClient和RestClient API。</li><li><a href="https://www.spring-doc.cn/spring-ai/1.1.3/api_advisors.html" target="_blank" rel="noreferrer">顾问API</a> - 封装了重复的生成式AI模式，转换发送给语言模型（LLMs）及从模型接收的数据，并在多种模型和应用场景之间提供可移植性。</li><li>对 <a href="https://www.spring-doc.cn/spring-ai/1.1.3/api_chatclient.html#_chat_memory" target="_blank" rel="noreferrer">聊天会话记忆</a> 和 <a href="https://www.spring-doc.cn/spring-ai/1.1.3/api_chatclient.html#_retrieval_augmented_generation" target="_blank" rel="noreferrer">检索增强生成（RAG）</a> 的支持。</li></ul><p>此功能集使您能够实现常见用例，例如“在文档上进行Q&amp;A”或“与文档聊天”。</p><ul><li><a href="https://www.spring-doc.cn/spring-ai/1.1.3/concepts.html" target="_blank" rel="noreferrer">概念部分</a> 提供了AI概念的高层概述以及它们在Spring AI中的表示方式。</li><li><a href="https://www.spring-doc.cn/spring-ai/1.1.3/getting-started.html" target="_blank" rel="noreferrer">入门指南</a> 部分向您展示如何创建您的第一个AI应用程序。 后续章节将深入探讨每个组件及常见使用场景，并采用以代码为中心的方法。</li></ul><hr><h1 id="人工智能概念" tabindex="-1">人工智能概念 <a class="header-anchor" href="#人工智能概念" aria-label="Permalink to &quot;人工智能概念&quot;">​</a></h1><p>本节介绍了Spring AI所使用的关键概念。我们强烈推荐仔细阅读它，以便理解Spring AI是如何实现的背后的思路。</p><h2 id="模型" tabindex="-1">模型 <a class="header-anchor" href="#模型" aria-label="Permalink to &quot;模型&quot;">​</a></h2><p>AI模型是设计用于处理和生成信息的算法，通常通过模仿人类认知功能来实现。 通过从大量数据中学习模式和见解，这些模型可以生成预测、文本、图像或其他输出，从而提升跨行业的各种应用。</p><p>有很多种类型的AI模型，每种模型都有其特定的适用场景。 尽管ChatGPT及其生成式AI能力通过文本输入和输出吸引了大量用户，但许多模型和公司提供了多样化的输入和输出。 在ChatGPT之前，许多人都对文本到图像生成模型（如Midjourney和Stable Diffusion）着迷。</p><p>以下表格根据输入和输出类型对几种模型进行了分类：</p><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/spring-ai-concepts-model-types.jpg" alt="Model types"></p><p>Spring AI目前支持能够处理语言、图像和音频输入与输出的模型。</p><p>上表的最后一行，接受文本作为输入并输出数字，更常见地被称为文本嵌入，表示用于人工智能模型的内部数据结构。 Spring AI对嵌入的支持，使其能够实现更复杂的使用场景。</p><p>区别于其他模型，像GPT这样的模型之所以脱颖而出，主要是因为它们具有预训练特性，正如GPT-P所体现的那样——生成式对话预训练的 transformer 模型。 这一特性使AI成为一种通用的开发者工具，无需具备深厚的机器学习或模型训练背景。</p><h2 id="提示" tabindex="-1">提示 <a class="header-anchor" href="#提示" aria-label="Permalink to &quot;提示&quot;">​</a></h2><p>提示是指导人工智能模型生成特定输出的基础语言输入的基础。对于熟悉ChatGPT的用户来说，提示似乎只是对话框中输入的文本，随后发送到API。然而，提示包含的内容远不止这些。在许多AI模型中，提示文本不仅是一个简单的字符串。</p><p>ChatGPT的API包含多个提示文本输入，每个输入都有一个特定的角色。例如，系统角色告诉模型应该如何行为并设定互动的上下文。此外，用户角色通常是用户的输入。</p><p>恰当地撰写提示（prompts）既是一门艺术又是一门科学。ChatGPT是为人类对话设计的，而不是像使用SQL一样“提问”。与传统SQL不同，使用AI模型时需要像与他人交流一样与之对话。</p><p>交互模式的重要性如此之高，以至于&quot;提示工程学&quot;已经发展成为一个独立的学科。 不断改进提示的有效性正在迅速发展出一系列技巧。 花时间设计一个提示可能会显著提高输出结果。</p>',22)),e("p",null,[r[4]||(r[4]=t("提示的共享已成为一种共同的实践，目前关于这一主题的学术研究正方兴未艾。 作为一个反直觉的例子（例如，与SQL形成对比），最近发表的一篇研究论文发现，",-1)),n(a,{color:"#ff0000"},{default:i(()=>[...r[3]||(r[3]=[t("一个非常有效的提示可以以“深呼吸并逐步完成这项任务”开头的短语开始",-1)])]),_:1}),r[5]||(r[5]=t("。这表明语言的重要性。 我们还不完全了解如何充分利用之前版本（例如ChatGPT 3.5）的技术效果，更不用说正在开发的新版本了。",-1))]),r[17]||(r[17]=p('<h3 id="提示模板" tabindex="-1">提示模板 <a class="header-anchor" href="#提示模板" aria-label="Permalink to &quot;提示模板&quot;">​</a></h3><p>创建有效的提示需要确定请求的上下文，并将请求中的部分替换为用户输入的具体值。</p><p>流程图：提示创建与管理 Spring AI 采用传统的文本型模板引擎进行提示的创建与管理。 Spring AI 采用 OSS 库 <a href="https://www.stringtemplate.org/" target="_blank" rel="noreferrer">字符串模板库</a> 来实现这一功能。</p><p>例如，考虑一个简单的提示模板：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Tell me a {adjective} joke about {content}.</span></span></code></pre></div><p>在Spring AI中，提示模板可以类比于Spring MVC架构中的“视图”。通常提供一个模型对象（ <code>java.util.Map</code> ），用于填充模板中的占位符。渲染后的字符串成为供AI模型使用的提示内容。</p><p>模型收到的提示数据格式存在显著的变化和多样性。最初以简单的字符串形式存在，后来发展到包含多个消息，每个消息中的字符串都代表了模型的特定角色。</p><h2 id="嵌入模型" tabindex="-1">嵌入模型 <a class="header-anchor" href="#嵌入模型" aria-label="Permalink to &quot;嵌入模型&quot;">​</a></h2><p>嵌入是文本、图像或视频的数值表示，用于捕捉输入之间的关系。</p><p>嵌入式技术通过将文本、图像和视频转换为浮点数数组来工作，这些数组被称为向量。 这些向量旨在捕捉文本、图像和视频的意义。 嵌入数组的长度称为向量的维度。</p><p>通过计算两段文本向量之间的数值距离，应用程序可以确定生成这些向量的对象之间的相似性。</p><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/spring-ai-embeddings.jpg" alt="Embeddings"></p><p>作为一名探索人工智能的Java开发者，深入理解这些向量表示的复杂数学理论或具体实现并不是必需的。 理解它们在AI系统中的角色和功能就足够了，尤其是在将AI功能整合到您的应用中时。</p><p>嵌入在诸如检索增强生成（RAG）之类的实用应用中尤其相关。它们使得数据可以表示为语义空间中的点，类似于欧几里得几何中的二维空间，但处于更高维度。这意味着，就像欧几里得几何中平面内的点根据其坐标可以接近或远离彼此一样，在语义空间中，点的接近程度反映了它们在含义上的相似性。关于类似主题的句子在这个多维空间中被放置得更近，就像在图表中，点彼此靠近。这种接近有助于任务如文本分类、语义搜索，甚至产品推荐，因为AI可以基于其“位置”在扩展的语义空间中辨别和分组相关概念。</p><p>这个语义空间可以被视为一个向量。</p><h2 id="token" tabindex="-1">token <a class="header-anchor" href="#token" aria-label="Permalink to &quot;token&quot;">​</a></h2><p>Token是AI模型中处理文本的基本单位。 当模型接收输入时，会将单词转换为Token；在生成输出时，会将Token转换回单词。</p><p>通常，一个Token大致相当于75%个Word。作为参考，莎士比亚的《 complete works》大约900,000个Word，其转换后token数量约为120万个。</p><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/spring-ai-concepts-tokens.png" alt="Tokens"></p><p>核心指令 1. **准确翻译**：保持原文的语义和语气，译文需自然流畅，符合中文表达习惯。 2. **保留格式**：保留原文的段落结构、换行符和标点符号。如果原文包含特殊的占位符（如 {name} 或 %s），请原样保留，不要翻译。 3. **输出限制**：直接输出翻译后的中文简体文本。不要包含“好的”、“这是翻译结果”等任何对话性文字或解释，也不要使用 Markdown 代码块标记。 待翻译文本 Perhaps more important is that Tokens = Money. In the context of hosted AI models, your charges are determined by the number of tokens used. Both input and output contribute to the overall token count.</p><p>此外，模型还受到token限制，这限制了单次API调用处理的文本量。</p><p>例如，ChatGPT3的 tokens 限制为4K，而GPT4提供了8K、16K和32K等多种选择。 Anthropic的Claude AI模型设置有100K tokens限制，而Meta近期的研究则推出了1M tokens限制的模型。</p><p>要使用GPT-4对莎士比亚的作品进行总结，你需要制定软件工程策略，将数据拆分并在模型的上下文窗口限制范围内进行呈现。 Spring AI项目可以帮你完成这项任务。</p><h2 id="结构化输出" tabindex="-1">结构化输出 <a class="header-anchor" href="#结构化输出" aria-label="Permalink to &quot;结构化输出&quot;">​</a></h2><p>传统上，AI模型的输出总是以0的形式呈现，即使你要求以JSON格式回复。它可能是一个正确的JSON字符串，但并不是一个JSON数据结构。它只是一个简单的字符串。此外，将“JSON”作为提示的一部分并不是100%准确。</p><p>这种复杂性导致了一个专门领域的发展，该领域涉及创建提示以生成所需输出，随后将生成的简单字符串转换为可应用的数据结构。</p><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/structured-output-architecture.jpg" alt="Structured Output Converter Architecture"></p><p><a href="https://www.spring-doc.cn/spring-ai/1.1.3/api_structured-output-converter.html#_structuredoutputconverter" target="_blank" rel="noreferrer">结构化输出转换</a> 采用精心设计的提示，通常需要多次与模型交互以实现预期的格式化效果。</p><h2 id="将您的数据与api集成到ai模型中" tabindex="-1">将您的数据与API集成到AI模型中 <a class="header-anchor" href="#将您的数据与api集成到ai模型中" aria-label="Permalink to &quot;将您的数据与API集成到AI模型中&quot;">​</a></h2><p>如何让AI模型在没有被训练的情况下获取信息？</p><p>请注意，GPT 3.5/4.0数据集仅扩展至2021年9月。 因此，模型表示，它不知道那些需要超出该日期知识的问题的答案。 有趣的是，这个数据集大约有650GB。</p><p>有三种方法存在，用于自定义AI模型以整合你的数据：</p><ul><li><strong>微调</strong> ：这是一种传统机器学习技术，涉及对模型进行调整并改变其内部权重。 然而，对于机器学习专家来说，这是一个具有挑战性的过程，尤其是对于像GPT这样的模型，由于其规模巨大，其资源需求极为密集。此外，有些模型可能不提供此功能。</li><li><strong>提示填充</strong> ：一种更实用的替代方法是将数据嵌入到模型收到的提示中。在模型的token限制内，需要使用一些技巧在模型的上下文窗口中呈现相关数据。 这种方法在非正式用语中被称为“stuffing the prompt”。 Spring AI库帮助您实现基于“stuffing the prompt”技术的解决方案，否则已知为 <a href="https://www.spring-doc.cn/spring-ai/1.1.3/concepts.html#concept-rag" target="_blank" rel="noreferrer">检索增强生成（RAG）</a> 。</li></ul><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/spring-ai-prompt-stuffing.jpg" alt="Prompt stuffing"></p><ul><li><strong><a href="https://www.spring-doc.cn/spring-ai/1.1.3/concepts.html#concept-fc" target="_blank" rel="noreferrer">工具调用</a></strong>: 这种技术允许注册工具(用户自定义服务)将大规模语言模型与外部系统API连接起来。 Spring AI极大地简化了编写代码以支持 <strong><a href="https://www.spring-doc.cn/spring-ai/1.1.3/api_tools.html" target="_blank" rel="noreferrer">工具调用</a></strong> <a href="https://www.spring-doc.cn/spring-ai/1.1.3/api_tools.html" target="_blank" rel="noreferrer">所需的代码。</a></li></ul><h3 id="增强检索生成" tabindex="-1">增强检索生成 <a class="header-anchor" href="#增强检索生成" aria-label="Permalink to &quot;增强检索生成&quot;">​</a></h3><p>检索增强生成（RAG）作为一种技术逐渐兴起，旨在解决将相关数据整合到提示中以提高AI模型准确回答的挑战。</p><p>该方法采用批处理风格的编程模型，其中任务从文档中读取非结构化数据，对其进行转换，然后写入向量数据库。 从整体来看，这是一项抽取、转换和加载（ETL）管道。 向量数据库在RAG技术的检索部分中被使用。</p><p>在将未结构化数据加载到向量数据库的过程中，一个至关重要的步骤是将原始文档拆分成更小的片段。 拆分原始文档为更小的片段的过程包含两个关键步骤：</p><ol><li>将文档分成部分时，必须在保持内容语义边界的同时，将其分成部分。 例如，在一个包含段落和表格的文档中，一个人应该避免在段落或表格中间分割文档。 对于代码，避免在方法实现中间分割代码。</li><li>将文档的部分进一步划分成部分，使其每个部分的大小占AI模型token限制的小百分比。</li></ol><p>在RAG中，处理用户输入是下一阶段的工作。 当用户的问题由AI模型回答时，不仅问题本身，所有“相似的”文档碎片都会被放入prompt中发送给AI模型。 这是因为向量数据库非常擅长找到相似的内容。</p><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/spring-ai-rag.jpg" alt="Spring AI RAG"></p><ul><li>The <a href="https://www.spring-doc.cn/spring-ai/1.1.3/api_etl-pipeline.html" target="_blank" rel="noreferrer">ETL管道</a> 进一步提供关于 orchestrate 数据从数据源抽取和存储到结构化向量存储的信息，确保数据以最佳格式存储，以便在传递给 AI 模型时实现高效的检索。</li><li>The <a href="https://www.spring-doc.cn/spring-ai/1.1.3/api_chatclient.html#_retrieval_augmented_generation" target="_blank" rel="noreferrer">聊天客户端 - RAG</a> 解释了如何在您的应用中启用 RAG 能力。</li></ul><h3 id="工具调用" tabindex="-1">工具调用 <a class="header-anchor" href="#工具调用" aria-label="Permalink to &quot;工具调用&quot;">​</a></h3><p>大语言模型（LLMs）在训练后被固化，导致知识陈旧，且无法访问或修改外部数据。</p><p>大语言模型（LLMs）通过工具调用机制实现自我服务注册，以将外部系统与大语言模型的API连接起来。这些系统能够提供实时数据给LLMs，并代为执行数据处理操作。</p><p>Spring AI大大简化了需要编写以支持工具调用的代码。 它会为你管理工具调用对话。 你可以提供一个带有 <code>@Tool</code> 注释的方法的工具，并将其提供到你的提示选项中，以便模型能够访问它。 此外，你可以在单个提示中定义和引用多个工具。</p><p><img src="https://obsidian-picture.oss-cn-shenzhen.aliyuncs.com/luoblog/tool-calling-01.jpg" alt="The main sequence of actions for tool calling"></p><ol><li>当我们希望将一个工具提供给模型时，我们会将其定义包含在聊天请求中。每个工具定义包含名称、描述和输入参数的schema。</li><li>当模型决定调用工具时，它会发送一个响应，包含工具名称和基于定义的模式的输入参数。</li><li>这个应用负责使用工具名来识别并执行工具，并带有提供的输入参数。</li><li>工具调用的结果将由应用程序处理。</li><li>应用程序将工具调用的结果返回给模型。</li><li>该模型使用工具调用结果作为额外的上下文来生成最终响应。</li></ol><p>遵循 <a href="https://www.spring-doc.cn/spring-ai/1.1.3/api_tools.html" target="_blank" rel="noreferrer">工具调用</a> 文档，以获得进一步了解如何使用此功能以不同AI模型的详细信息。</p><h2 id="评估ai回答" tabindex="-1">评估AI回答 <a class="header-anchor" href="#评估ai回答" aria-label="Permalink to &quot;评估AI回答&quot;">​</a></h2><p>有效评估AI系统对用户请求的输出至关重要，以确保最终应用的准确性和实用性。 几种新兴技术可以利用预训练模型本身来实现这一目的。</p><p>这个评估过程涉及分析生成的响应是否符合用户意图和查询的上下文。相关性、连贯性和事实准确性等指标用于评估AI生成的响应质量。</p>',53)),e("p",null,[r[7]||(r[7]=t("一种方法是",-1)),n(a,{color:"#ff0000"},{default:i(()=>[...r[6]||(r[6]=[t("同时呈现用户请求和人工智能模型的响应",-1)])]),_:1}),r[8]||(r[8]=t("，向模型询问该响应是否与提供的数据一致。",-1))]),e("p",null,[r[10]||(r[10]=t("此外，",-1)),n(a,{color:"#ff0000"},{default:i(()=>[...r[9]||(r[9]=[t("利用向量数据库存储的信息作为补充数据，可以增强评估过程",-1)])]),_:1}),r[11]||(r[11]=t("，有助于确定响应的相关性。",-1))]),r[18]||(r[18]=e("p",null,[t("Spring AI项目提供了0号 "),e("code",null,"API"),t(" ，目前提供了评估模型响应基本策略的接口。请参考 评估测试 文档以获取进一步信息。")],-1))])}const w=o(g,[["render",d]]);export{b as __pageData,w as default};
